import{_ as e,o as a,c as o,a3 as d}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"布局与主题","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/theme.md","filePath":"frontend/theme.md","lastUpdated":1786258579000}'),r={name:"frontend/theme.md"};function s(i,t,l,n,c,h){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="布局与主题" tabindex="-1">布局与主题 <a class="header-anchor" href="#布局与主题" aria-label="Permalink to &quot;布局与主题&quot;">​</a></h1><p>外观相关的一切：布局结构、Tailwind v4 的用法与陷阱、主题系统、偏好同步。</p><h2 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to &quot;布局&quot;">​</a></h2><p><code>packages/layouts/</code> 提供整套外壳：侧边栏、顶栏、标签页（tabbar）、内容区、页脚。</p><h3 id="滚动模型" tabindex="-1">滚动模型 <a class="header-anchor" href="#滚动模型" aria-label="Permalink to &quot;滚动模型&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">滚动源不是 <code>window</code></p><p>布局根是<strong>定高</strong>的（<code>h-full</code>），滚动发生在<strong>内容容器内部</strong>。这意味着：</p><ul><li>监听 <code>window</code> 的 scroll 事件拿不到滚动；</li><li>需要吸顶/吸底的整屏页直接用 <code>h-full</code> 或 <code>XPageShell</code> 即可；</li><li><strong>不要写 per-page 的 JS 定高 hack</strong>。</li></ul><p>回到顶部、路由切换重置滚动都已由布局适配器统一处理。</p></div><h2 id="样式-tailwind-css-4-css-first" tabindex="-1">样式：Tailwind CSS 4（CSS-first） <a class="header-anchor" href="#样式-tailwind-css-4-css-first" aria-label="Permalink to &quot;样式：Tailwind CSS 4（CSS-first）&quot;">​</a></h2><p>用 <code>@tailwindcss/vite</code> + <strong>CSS-first <code>@theme</code></strong>（入口 <code>src/styles/index.css</code>），<strong>没有 JS config 文件</strong>。</p><p>三条关键约定：</p><table tabindex="0"><thead><tr><th>约定</th><th>说明</th></tr></thead><tbody><tr><td><strong>只引入 theme + utilities，不引入 preflight</strong></td><td>基础重置由 Naive UI 与 <code>design/global.css</code> 的最小重置负责，避免与 Naive UI 打架</td></tr><tr><td>颜色令牌用运行时 HSL CSS 变量</td><td><code>--color-primary: hsl(var(--primary))</code> 等，保证明暗与主题色能动态切换</td></tr><tr><td>暗色走 class 策略</td><td><code>@custom-variant dark (&amp;:where(.dark, .dark *))</code></td></tr></tbody></table><h3 id="嵌套-dark-的坑" tabindex="-1">嵌套 <code>.dark</code> 的坑 <a class="header-anchor" href="#嵌套-dark-的坑" aria-label="Permalink to &quot;嵌套 \`.dark\` 的坑&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">深色侧栏里 <code>bg-*</code> / <code>text-*</code> 不变暗</p><p><code>@theme</code> 里声明的 <code>--color-*</code> <strong>只在 <code>:root</code> 解析</strong>。深色侧栏、深色子栏、深色顶栏这类<strong>嵌套 <code>.dark</code></strong> 的容器里，Tailwind 的颜色工具类拿不到暗色值，表现是「局部深色区域里的元素还是亮色」。</p><p>修法：在 <code>variables.css</code> 的 <strong><code>:root, .dark</code></strong> 块里<strong>重新声明全部 <code>--color-*</code></strong>，让嵌套作用域也能解析到。</p></div><h2 id="主题系统" tabindex="-1">主题系统 <a class="header-anchor" href="#主题系统" aria-label="Permalink to &quot;主题系统&quot;">​</a></h2><p><code>useTheme()</code>（<code>~/hooks/useTheme.ts</code>）管理外观：</p><table tabindex="0"><thead><tr><th>维度</th><th>可调</th></tr></thead><tbody><tr><td>明暗</td><td>亮 / 暗 / 跟随系统</td></tr><tr><td>主题色</td><td>任意品牌色</td></tr><tr><td>形状</td><td>圆角</td></tr><tr><td>排版</td><td>字号</td></tr></tbody></table><h3 id="material-you-动态取色" tabindex="-1">Material You 动态取色 <a class="header-anchor" href="#material-you-动态取色" aria-label="Permalink to &quot;Material You 动态取色&quot;">​</a></h3><p><strong>从单个品牌色派生整套和谐色阶</strong>——辅色、容器色、前景色、聚焦环、带品牌色相的中性色，明暗自适应，以内联 CSS 变量写到根元素。</p><p>所以<strong>换主题色不需要改任何 CSS</strong>：改一个色值，整套配色跟着重算。</p><p>主色、明暗、圆角、字号变化都会同步到 CSS 变量，非 Naive 的自定义元素也能直接用这些变量。</p><h3 id="切换动画" tabindex="-1">切换动画 <a class="header-anchor" href="#切换动画" aria-label="Permalink to &quot;切换动画&quot;">​</a></h3><p><code>startViewTransition</code> 从点击处圆形扩散——明暗切换时的视觉过渡。</p><h2 id="偏好同步" tabindex="-1">偏好同步 <a class="header-anchor" href="#偏好同步" aria-label="Permalink to &quot;偏好同步&quot;">​</a></h2><p>UI 偏好走 <code>UserSettingAppService</code>，按<strong>场景 + key</strong> 存取：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>localStorage（事实源）</span></span>
<span class="line"><span>   ↕</span></span>
<span class="line"><span>后端 SysUserSetting（用户 × 场景 × 设置键）</span></span>
<span class="line"><span>   ↕ SignalR UserSettingChanged</span></span>
<span class="line"><span>其它设备已打开的页面即时应用</span></span></code></pre></div><p>三条策略：</p><ol><li><strong>localStorage 是事实源</strong>——后端加载成功则覆盖本地，保存失败静默忽略（尽力而为，不阻断交互）。</li><li><strong>服务端不解释 value</strong>，只作跨端状态载体。</li><li>其它设备保存后经 SignalR 广播实时应用。</li></ol><p>Schema 页的列设置、搜索设置、个人视图按 <code>pageCode</code> 走同一套机制，见 <a href="./schema-page#偏好与视图">Schema 驱动页面</a>。</p><div class="tip custom-block"><p class="custom-block-title"><code>pageCode</code> 要稳定</p><p>偏好按 <code>pageCode</code> 存储，<strong>改了等于用户的所有个性化配置丢失</strong>。页面上线后不要再动它。</p></div><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>深色区域里的元素还是亮色</td><td>嵌套 <code>.dark</code> 令牌问题，见上面的 danger 块</td></tr><tr><td>改了主题色但某些地方没变</td><td>那些地方写死了颜色值，没用 CSS 变量</td></tr><tr><td>页面滚不动 / 吸顶失效</td><td>用了 <code>window</code> 滚动的假设；改用 <code>h-full</code> 或 <code>XPageShell</code></td></tr><tr><td>样式被 Naive UI 覆盖</td><td>preflight 是<strong>故意关闭</strong>的，别去打开——会破坏 Naive UI</td></tr><tr><td>偏好换台设备就没了</td><td>后端保存失败被静默忽略了，查接口是否可用</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./i18n">国际化</a>：文案与枚举标签</li><li><a href="./icon">字体图标</a>：图标用法与离线限制</li><li><a href="./components">常用组件</a>：布局相关组件</li><li><a href="./introduction">框架简介</a>：前端分层与启动引导</li></ul>`,32)])])}const u=e(r,[["render",s]]);export{g as __pageData,u as default};
